-- Generated from reviewed local artifacts; safe to re-run.
-- This migration does not edit lyrics, titles, singers, statuses, or taxonomy.
-- Language updates are restricted to rows already marked mismatch_confirmed.
-- Fasting suitability is separate from canonical fasting-season occasions.

begin;

create table if not exists public.mezmur_fasting_suitability (
  mezmur_import_id uuid primary key,
  themes text[] not null default '{}',
  specific_occasion_slugs text[] not null default '{}',
  confidence text not null check (confidence in ('high', 'medium', 'low')),
  supporting_lyric_excerpt text not null default '',
  classification_explanation text not null default '',
  review_required boolean not null default true,
  evidence_source text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.mezmur_fasting_suitability enable row level security;
revoke all on table public.mezmur_fasting_suitability from public, anon;
grant select, insert, update, delete on table public.mezmur_fasting_suitability to authenticated;
grant all on table public.mezmur_fasting_suitability to service_role;

drop policy if exists mezmur_fasting_suitability_staff_all on public.mezmur_fasting_suitability;
create policy mezmur_fasting_suitability_staff_all
on public.mezmur_fasting_suitability for all to authenticated
using (public.is_staff()) with check (public.is_staff());

insert into public.mezmur_fasting_suitability (
  mezmur_import_id, themes, specific_occasion_slugs, confidence,
  supporting_lyric_excerpt, classification_explanation, review_required, evidence_source
)
values
    ('0292a3c8-cecf-4b36-87a4-ed5e3e6962ac'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ንስሓስ ንዓዩ ዛነብሰይ ዘርሳህኩ', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "ሀጥያት"×2, "በደል"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('0b192072-c4c1-4c14-abb6-f3e3951f73e1'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ኦ እግዚአብሔር አብ አኃዜ ኩሉ መሐረነ ኦ ወልድ ዋህድ ኢየሱስ ክርስቶስ ተሣሃለነ /፪/ / ኦ ጰራቅሊጦስ መንፈሰ ጽድቅ ሥረይ /፪/ ለነ ሀሉ ምስሌነ /፪/', 'Main subject: Jesus Christ ("ኢየሱስ ክርስቶስ"×2, "ወልድ ዋሕድ"×2). Also: Holy Spirit ("ጰራቅሊጦስ"×2); Repentance ("መሐረነ"×2). Occasion evidence: Pentecost ("ጰራቅሊጦስ"×2).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('0d404b06-a2a3-4e5f-8488-ab58e80459c0'::uuid, array['repentance']::text[], array[]::text[], 'high', 'እስከ ሞት ነውና የክርስቶስ ፍቅሩ', 'Main subject: Jesus Christ ("ክርስቶስ"×3, "ጌታችን"×2, "ጌታዬ"×1). Also: Repentance ("ንስሐ"×1, "ሀጥያት"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('0d795464-f0c5-4a8a-ac7e-19de52ec5b85'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ነጽተው ንስሓ ገብተው / ከዓመት ዐውደ ዓመት ደርሰው', 'Theme-centred hymn: Repentance ("ንስሐ"×2); no single person or saint dominates. Occasion evidence: New Year / Enkutatash ("ዐውደ ዓመት"×2); Communion ("ሥጋ ወደሙ"×2).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('0da43b7d-0abb-4939-bf25-c9f165434972'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ይቅር በለን ባጠፋነው የፍቅር አባት የምህረት / ደግ ደጉን አሳየን ደስ ይበለን በአዲስ ዓመት', 'Theme-centred hymn: Repentance ("ይቅር በለን"×5); no single person or saint dominates. Occasion evidence: New Year / Enkutatash ("አዲስ ዓመት"×5).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('0e442b2c-9771-4464-bd6a-208f6f7a91d2'::uuid, array['repentance']::text[], array[]::text[], 'high', 'And bring forth my praise to glorify His name', 'Theme-centred hymn: Praise / Worship ("Praise"×6, "sing"×6, "glory"×1); no single person or saint dominates. Also: Repentance ("my sins"×5). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('13707f49-26df-4062-9429-55d498051cc1'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ስለመገብካቸው ቀዳሜ ሰማዕት', 'Main subject: Kidus Estifanos / Saint Stephen ("ቀዳሜ ሰማዕት"×7). Also: Repentance ("ይቅርታ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('175552b7-9b7b-4ae5-a1c7-46eb4de33782'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ብወድቅ እነሳለሁ ዳግም በንስሐ', 'Theme-centred hymn: Repentance ("ንስሐ"×2, "ኃጢአት"×3, "ኃጢአቴ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('1b781a31-8eec-4cef-b3e1-81d6584a73e6'::uuid, array['repentance']::text[], array[]::text[], 'high', 'የሰው ልጅ ተዘጋጅ በንስሓ ታጥበህ', 'Theme-centred hymn: Repentance ("ንስሐ"×2, "ኃጢአቴ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('2397b407-e923-4aa2-b079-76d0fde813da'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በበደልነው በደል ማረን እንላለን', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "በደል"×2, "ማረን"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('24f3057c-0c0d-4914-a9ff-e602bd2acf89'::uuid, array['repentance']::text[], array[]::text[], 'high', 'አማኑኤል ተመስገን ለዚህ ፍቅርህ ምን ልበልህ/2/', 'Main subject: Jesus Christ ("አማኑኤል"×5). Also: Repentance ("ሀጥያት"×4, "ኃጢያት"×2, "በደሌ"×1); Praise / Worship ("ተመስገን"×5). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('2abc210e-7ff2-4fdf-b2f7-a2cbf8939dd2'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ቸር አምላክ የእውነት ዳኛ፤ አማኑኤል ለኔ መታመኛ', 'Main subject: Jesus Christ ("አማኑኤል"×4). Also: Salvation ("አዳነኝ"×3); Repentance ("ኃጢአተኛ"×1, "እንባዬ"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('34b29d80-f518-4a26-8edd-07dfe60468fc'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ምሬሃለዉ በለኝ ስል ድንግል ማርያም /2/', 'Main subject: Virgin Mary ("ድንግል ማርያም"×10). Also: Repentance ("ማረኝ"×2, "ይቅርታ"×1, "ሀጥያቴ"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('36367d1d-8184-4fc1-8f33-f6247f39fa70'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'እንደ ቸርነትህ አቤቱ ፣ አንተ ይቅር በለን(፪x)', 'Theme-centred hymn: Repentance ("ይቅር በለን"×4); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('385af9d5-8b02-4af7-a324-92709400a9fc'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በሞትና በደም ሀጥያቴን ሸፍኖ', 'Theme-centred hymn: Repentance ("ሀጥያቴ"×1, "ማረኝ"×1, "በደሌ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('39e4a84f-bb0e-416f-a6bd-7d3d7366f44c'::uuid, array['repentance', 'mercy', 'prayer']::text[], array[]::text[], 'high', 'ይቅርታ/2/ ልበልህ ይቅርታ', 'Theme-centred hymn: Repentance ("ማረኝ"×4, "ይቅርታ"×2, "ይቅር በለኝ"×1); no single person or saint dominates. Also: Prayer ("እለምንሃለሁ"×4). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('4116eec6-2785-4b4e-a030-8b94b43424b3'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ክብሬ እኮ ነህ ኢየሱስ / ተሰቅለህ ያየሁህ ለሀጥያተኛው ለኔ', 'Main subject: Jesus Christ ("ኢየሱስ"×2). Also: Cross ("መስቀል"×2); Repentance ("በደል"×2, "ሀጥያት"×1). Occasion evidence: Siklet ("ተሰቅለህ"×2, "ተሰቀለ"×1, "ጎልጎታ"×1); Tinsae ("ፋሲካ"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('49b9b484-91fa-4b94-8f23-97c2b9ad6a8b'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ጴጥሮስ ተጸፅቶ ንስሃ እንዲገባ', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "በደላችን"×1, "ኃጢአቴ"×1); no single person or saint dominates. Also: Apostles ("ጴጥሮስ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('4cd7bb3c-e9a6-4777-97ce-57cb90e456f4'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'Guide me to repent, my Lord, almighty', 'Theme-centred hymn: Repentance ("my sins"×2, "repent"×1, "lord have mercy"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('51a6e811-0c2b-4825-9ee5-a95df7ca610a'::uuid, array['repentance']::text[], array[]::text[], 'high', 'የምስጋናን ቃል የፈለጉብኝ', 'Theme-centred hymn: Praise / Worship ("ምስጋና"×4); no single person or saint dominates. Also: Repentance ("እንባዬ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('540e52ab-55a2-475a-afd5-c991f78a255a'::uuid, array['repentance']::text[], array[]::text[], 'high', 'Jesus Christ is truly born and baptized for our sins / The waters became troubled, the Jordan turned to flee', 'Main subject: Jesus Christ ("Jesus Christ"×17). Also: Virgin Mary ("full of grace"×17); Repentance ("our sins"×12, "sins"×12); Holy Spirit ("Holy Spirit"×2). Occasion evidence: Timket ("jordan"×4).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('55687b9a-0af0-4f90-9a15-5f62a0027741'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ሐጢአቴን ሳታይብኝ', 'Theme-centred hymn: Repentance ("ኃጢአቴ"×1, "ይቅርታ"×1, "በደሌ"×1); no single person or saint dominates. Also: Praise / Worship ("ምስጋና"×1, "ተመስገን"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('5579d4ac-7343-4aa9-83b1-69968652368a'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'በገፋሁት ልኬት በጠፋሁት መጠን እየተከተለ', 'Theme-centred hymn: Repentance ("ጠፋሁ"×1, "ሀጥያት"×2, "ይቅርታ"×1); no single person or saint dominates. Also: Praise / Worship ("ምስጋና"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('5642afac-0ce3-458d-889d-11189a9feb5e'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ሽቱው ለፍቅርህ ነው ለንስሓ እንባ ።', 'Theme-centred hymn: Repentance ("ማረኝ"×2, "ንስሐ"×1, "ኃጢያት"×2); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('684aa530-ed36-4961-ae53-ddcd3953c3b7'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'በፍቅሩ ማረከኝ ጠራኝ በይቅርታው', 'Theme-centred hymn: Repentance ("ይቅርታ"×1, "ኃጢአተኛ"×1, "በደሌ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('5c45acad-41f9-42bf-a38f-2f8293f2e5e8'::uuid, array['repentance']::text[], array[]::text[], 'high', 'እኔ ግን ተመለስኩ ወደ ኃጢአቴ', 'Theme-centred hymn: Repentance ("ተመለስኩ"×1, "ኃጢአተኛ"×1, "ኃጢአቴ"×1); no single person or saint dominates. Also: Jesus Christ ("ክርስቶስ"×1, "ጌታዬ"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('5f6374ad-722d-4b77-9921-228333cec573'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ለምትጠራኝ ላንተ ማረኝ ይቅር በለኝ ይብቃኝ መበደሉ', 'Theme-centred hymn: Repentance ("ይቅር በለኝ"×1, "በደሌ"×1, "ማረኝ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('60653974-1135-4ef0-bee2-781e142420c2'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በንስሐ ማረን ከዓራተ ዝንጋኤ ከኃጥያት አልጋ', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "ማረን"×1, "ሀጥያት"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('6115e955-c530-4452-ba6b-ba1a1ad793fc'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ተመስገን ተመስገን ይላል የተጎበኘ ሰው / ዳዊትም ከበገናው ጋር በቅኔ ተነስቷል', 'Theme-centred hymn: Praise / Worship ("ተመስገን"×2, "ሃሌ ሉያ"×1, "ንሴብሖ"×1); no single person or saint dominates. Also: Repentance ("ይቅርታ"×2). Occasion evidence: Tinsae ("ተነሥቷል"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('6263e3ec-ec19-456a-aca1-ee848ac14fe3'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ስሙን እናመስግን እንዘምር በእልልታ', 'Theme-centred hymn: Praise / Worship ("ተመስገን"×8, "እናመስግን"×7, "እንዘምር"×1); no single person or saint dominates. Also: Jesus Christ ("ክርስቶስ"×1, "አማኑኤል"×1, "ጌታዬ"×1); Repentance ("ኃጢአት"×7). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('62d7a44d-2ea4-401d-9213-878f3968a447'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ፍቅሩን በንስሀ ስቦ ያመጣበት', 'Theme-centred hymn: Repentance ("ንስሐ"×2, "ኃጢአት"×2, "ኃጢአቴ"×1); no single person or saint dominates. Also: Apostles ("ጴጥሮስ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('656b08fe-76ca-42ce-b56e-108b67a12a5b'::uuid, array['repentance', 'prayer']::text[], array[]::text[], 'high', 'ድረሺልኝ ድንግል /ስምሽን ስጠራ//2/', 'Main subject: Virgin Mary ("ድንግል"×6, "ንዒ"×3). Also: Prayer ("እለምንሻለሁ"×3, "ድረሺልኝ"×3); Repentance ("በደሌ"×3). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('317bd373-31a6-4f95-acea-34f9063acee6'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'በንስሓ ውሃ አጥቤና ስድሼ/2/', 'Theme-centred hymn: Repentance ("ንስሐ"×2, "ይቅር በለኝ"×1, "በደል"×2); no single person or saint dominates. Also: Apostles ("ጴጥሮስ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('72bb10e8-1dd6-48a4-9b1a-6676b7028dae'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', '… አቤቱ ማረን አምላካችን', 'Theme-centred hymn: Repentance ("አቤቱ ማረን"×24, "ይቅር በለን"×9, "በደላችን"×9); no single person or saint dominates. Also: Virgin Mary ("ማርያም"×9); Jesus Christ ("መድኃኔዓለም"×2, "ጌታችን"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('7455b3bb-1f99-4c30-b2c9-3d80771fb944'::uuid, array['repentance']::text[], array[]::text[], 'high', 'የኛ መድኃኒዓለም ሞትን ድልአረገው…እሰይ የምስራች / አምላክሽ ተነስቷል ከሐጢአት ያነፃሽ…እሰይ የምስራች', 'Main subject: Jesus Christ ("መድኃኒዓለም"×1, "አማኑኤል"×1). Also: Praise / Worship ("እናመስግን"×1, "ምስጋና"×1, "እልል"×1); Virgin Mary ("ማርያም"×1); Repentance ("ኃጢአት"×2). Occasion evidence: Tinsae ("ተነሥቷል"×2, "ትንሣኤ"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('7774a468-f816-4d85-a9e4-3eec11f6182e'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ተወለደ ኢየሱስ አዳኝ ንጉሣችን', 'Main subject: Jesus Christ ("መሲሕ"×2, "ኢየሱስ"×1). Also: Repentance ("በደል"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('160a1a1b-2f9b-4f77-910f-1ec775e268b6'::uuid, array['repentance', 'prayer']::text[], array['tsome-nineveh']::text[], 'high', 'ተመልሶ አረገ/2/ በጾምና ጸሎት/2/ / ነነዌን ሊያቃጥል የወረደው እሳት/2/', 'Theme-centred hymn: Prayer ("ጸሎት"×3); no single person or saint dominates. Occasion evidence: Tsome Nineveh ("ነነዌ"×2, "ዮናስ"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('7e856788-660b-4c22-800c-57222345bace'::uuid, array['repentance']::text[], array[]::text[], 'high', 'አላሰበብኝም ሀጥያቴን', 'Theme-centred hymn: Repentance ("በደሌ"×2, "ሀጥያቴ"×1, "ሀጥያት"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('7edd14f1-ba77-4afb-8eed-9d615f0f7a5c'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ማርያም የኔ እመቤቴ / ለመስቀል ለታ ለደመራው', 'Main subject: Virgin Mary ("ማርያም"×3, "ድንግል"×3, "እመቤት"×2). Also: Repentance ("ንስሐ"×2, "ማረኝ"×2, "ኃጢአት"×1); Praise / Worship ("ሃሌ ሉያ"×14, "ምስጋና"×1); Jesus Christ ("መድኃኔዓለም"×2, "ጌታዬ"×2). Occasion evidence: Meskel ("ደመራ"×1); New Year / Enkutatash ("እንቁጣጣሽ"×1, "መስከረም"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('8374c7e0-4718-474a-8d9b-15bb9788c462'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ማርያመይ ማልድለይ ደጊም ከይወድቕ ልበይ/2/', 'Main subject: Virgin Mary ("ማርያም"×2). Also: Repentance ("ንስሐ"×1, "ኃጢአት"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('8a8136c3-ed4d-4c89-a1ea-97af7a17e98e'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ይቅር በለኝ ጌታ ፣ ይብዛልኝ ቸርነት ። / ብሉ ብለህ ሰጥተህ ፣ ሥጋና ደምህን', 'Theme-centred hymn: Repentance ("ይቅር በለኝ"×1, "ኃጢአት"×2, "ኃጢአተኛ"×1); no single person or saint dominates. Occasion evidence: Communion ("ሥጋ … ደም (Body and Blood)"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('8be97736-d161-4647-ba78-762643adb7b3'::uuid, array['repentance', 'prayer']::text[], array[]::text[], 'high', 'ማረኝ እና ይብቃኝ ለሐጥያት መዝመቱ', 'Theme-centred hymn: Repentance ("ማረኝ"×2, "ሀጥያት"×1, "ኃጢአት"×1); no single person or saint dominates. Also: Prayer ("እርዳኝ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('8e365ff5-5059-4162-ab56-f1843d07753c'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'በረከሰ አንደበት ይቅርታን ለመንኩህ', 'Theme-centred hymn: Repentance ("ይቅርታ"×1, "ኃጢአቴ"×1, "በደል"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('4f431d3a-167e-488f-8727-432a053a4aba'::uuid, array['repentance', 'mercy', 'prayer']::text[], array[]::text[], 'high', 'አስከ አንገቴ ደርሶ የኃጢአቴ ብዛት', 'Theme-centred hymn: Repentance ("ኃጢአቴ"×2, "ይቅርታ"×2, "ኃጢአት"×2); no single person or saint dominates. Also: Prayer ("ድረስልኝ"×1, "ጠብቀኝ"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('90a2d0a9-7546-4d57-9bed-56ac1792f5c8'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'በይቅርታ መጣሁ ተቀበለኝ', 'Theme-centred hymn: Repentance ("ይቅርታ"×4, "ኃጢአቴ"×1); no single person or saint dominates. Also: Praise / Worship ("ዝማሬ"×10). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('9bc8f75e-2dc8-48c1-b2ab-396bfc21c058'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ሀሌ ሀሌ ሉያ ሃሌ ሉያ / ቡሄ በሉ ሆ ቡሄ በሉ ሆ ልጆች ሁሉ ሆ', 'Theme-centred hymn: Praise / Worship ("ሃሌ ሉያ"×85, "ይመስገን"×3, "እንዘምር"×1); no single person or saint dominates. Also: Repentance ("ንስሐ"×1, "ኃጢያት"×1); Jesus Christ ("ክርስቶስ"×1). Occasion evidence: Debre Tabor ("ደብረ ታቦር"×19, "ታቦር"×4, "ቡሄ"×3); New Year / Enkutatash ("ዐውደ ዓመት"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('9d2c8a50-122d-4e06-89b1-adef22911a64'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ከባቴ ኣበሳይ ሸፋኒ ንጉደይ ኣማኑኤል', 'Main subject: Jesus Christ ("አማኑኤል"×4, "ጎይታይ"×1). Also: Repentance ("ኃጢአት"×6, "መሐረኒ"×4, "በደል"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('9f9f2735-1783-4fb0-b1ce-bc3ba319ccda'::uuid, array['repentance']::text[], array[]::text[], 'high', 'እየሱስ ክርስቶስ ምግቤና መጠጤ', 'Main subject: Jesus Christ ("ጌታዬ"×13, "ክርስቶስ"×1, "እየሱስ"×1). Also: Repentance ("ኃጢአተኛ"×6). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('a1d10712-a54e-4b2f-9e2f-46c99e425b06'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በታቆመኝ ኖሮ በደሌን ከድነህ፣', 'Theme-centred hymn: Repentance ("በደል"×3, "ኃጢአት"×2, "በደሌ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('a281fa45-402b-4e10-b486-bd26f96f809e'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በንስሐ አዲስ አድርጎናል', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "በደላችን"×1, "ኃጢያት"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('a4f8d330-6c4d-4edf-8014-920c8417b990'::uuid, array['repentance']::text[], array[]::text[], 'high', 'አመሰግናለሁ ድንግል እመቤቴን', 'Main subject: Virgin Mary ("ድንግል"×4, "እመቤቴ"×2, "እናቴ"×1). Also: Praise / Worship ("እዘምራለሁ"×2, "አመሰግናለሁ"×1); Repentance ("እንባዬ"×3). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('ae9bc345-8234-4a37-9b8e-d924428d42e6'::uuid, array['repentance']::text[], array[]::text[], 'high', 'God will accept us He will forgive us (2) with His righteousness', 'Theme-centred hymn: Repentance ("forgive us"×6, "Repentance"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('afb14214-07ab-45fe-9aec-b681c65c1009'::uuid, array['repentance']::text[], array[]::text[], 'high', 'እኔ ለንስሃ በውሃ አጠመቅኃችሁ / ለሰርጉ ሊጠራን መቷል እና በጉ', 'Theme-centred hymn: Repentance ("ንስሐ"×3); no single person or saint dominates. Also: Salvation ("መዳን"×2). Occasion evidence: Wedding ("ሰርግ"×2).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('b11db480-f838-45b7-9a9c-f662ad531913'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ጊዮርጊስ እግዚአብሔር ዘኀ ረየከ', 'Main subject: Kidus Giorgis ("ጊዮርጊስ"×2). Also: Praise / Worship ("ውዳሴ"×1, "ስብሐት"×1); Repentance ("በደሌ"×1, "ኃጢአት"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('b204468d-ad43-4926-8555-b2f649f299b5'::uuid, array['repentance']::text[], array[]::text[], 'high', 'እንደ አማኑኤል #ማንም የለም /2/', 'Main subject: Jesus Christ ("አማኑኤል"×3, "ጌታዬ"×2). Also: Repentance ("ኃጢያት"×1, "በደል"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('b4b4b601-23ca-42b9-8d61-9dfec469180e'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ነውሬ በዝቶ በኃጢአቴ የከረፋው', 'Theme-centred hymn: Repentance ("ኃጢአቴ"×2, "ኃጢአት"×1, "በደል"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('b7990c49-8e5a-408c-8b7a-5dab8925eb17'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ቸርነትህ በዝቶ ይቅርታህ ያቆመኝ', 'Theme-centred hymn: Repentance ("ሀጥያት"×2, "ይቅርታ"×1, "ሀጥያቴ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('c05cc36a-560a-483b-8c9c-62c509461ce9'::uuid, array['repentance']::text[], array[]::text[], 'high', 'Lord, forgive me.', 'Theme-centred hymn: Repentance ("forgive me"×16, "my sins"×14, "Repentance"×2); no single person or saint dominates. Also: Cross ("the cross"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('c07e2571-594b-4602-9ad5-99b8dd71ed86'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በደልህን አምነህ ንስሀ ግባና', 'Theme-centred hymn: Repentance ("ንስሐ"×3, "ኃጢያት"×2, "ተመለስ"×2); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('c615aeaa-0cf2-44d1-ab75-caa8dcc04d20'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'በንስሀ ሳላጥበው እድፌን /2/', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "ይቅር በለኝ"×1, "ኃጢያት"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('c89328de-d3aa-4e9e-a634-9dabfcfeda3c'::uuid, array['repentance']::text[], array[]::text[], 'high', 'የብርሃን ደጅ ናት ድንግል እናታችን', 'Main subject: Virgin Mary ("ድንግል"×4, "እናታችን"×1). Also: Repentance ("ሀጥያቴ"×1, "ኃጢአት"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('c8b43dbc-958b-4eea-9623-a565ea61c3dd'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'የአምላክ እናት እመቤታችን / ደጅ ጠናሁ ቆይቼ ኪዳነምህረትን', 'Main subject: Virgin Mary ("እናቴ"×5, "ኪዳነምሕረት"×2, "የአምላክ እናት"×1). Also: Repentance ("እንባዬ"×4). Occasion evidence: Kidane Mihret ("ኪዳነምሕረት"×2).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('d3bb48c7-56ed-4a71-a8df-b46b0d997918'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ይታደገናል መድሃኒዓለም', 'Main subject: Jesus Christ ("መድኃኒዓለም"×5). Also: Repentance ("በደላችን"×1, "ኃጢያት"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('508f2d9c-1683-4db6-b11c-006d36a3c9ba'::uuid, array['repentance']::text[], array[]::text[], 'high', 'አምላካችን መድኃኔዓለም ነው', 'Main subject: Jesus Christ ("መድኃኔዓለም"×3). Also: Praise / Worship ("ምስጋና"×2, "እናመስግን"×1, "እልል"×1); Salvation ("ያዳነን"×1, "ከሞት"×2); Repentance ("ኃጢአት"×1, "በደል"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('d93a6fb5-45f1-4b62-9c41-aff6ec7b2203'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'Forgive me, Lord Have mercy, Forgive /2/', 'Theme-centred hymn: Repentance ("forgive me"×10, "lord have mercy"×8, "repent"×2); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('dc6087ec-e6b0-46d3-8819-085305934191'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'አድለኝ የንስሃ ኤድሜን', 'Theme-centred hymn: Repentance ("ንስሐ"×1, "ይቅርታ"×1, "ሀጥያት"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('de56d947-4bce-472c-bff9-038b44fbe655'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'Though I''m a sinner He shows mercy', 'Theme-centred hymn: Repentance ("sinner"×4); no single person or saint dominates. Also: Salvation ("saved me"×40). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('e5c7810a-6814-4aca-be3b-0513f81b6d5d'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በደሌን ከድነህ አቁመኝ', 'Theme-centred hymn: Repentance ("ማረኝ"×6, "በደሌ"×2, "ሀጥያት"×1); no single person or saint dominates. Also: Angels ("መልአክ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('e7f24a15-2849-48c4-ac50-01e8d26ce8f7'::uuid, array['repentance']::text[], array[]::text[], 'high', 'አሳልፈህ እንዳትሰጠኝ ለሀጢአቴ', 'Theme-centred hymn: Repentance ("ማረኝ"×3, "በደል"×3, "ኃጢአቴ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('e87145fe-8002-424e-8696-348a5b79696d'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በዳዊት ምስጋና በያሬድ ዝማሬ', 'Theme-centred hymn: Praise / Worship ("ምስጋና"×2, "እዘምራለሁ"×1, "ዝማሬ"×1); no single person or saint dominates. Also: Repentance ("ኃጢአት"×2); Salvation ("ከሞት"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('eb29781a-9b34-4dfe-b95a-69496130b3ad'::uuid, array['repentance', 'mercy', 'prayer']::text[], array[]::text[], 'high', 'እግዚኦ መሐረነ ክርስቶስ። ስማን እግዚአብሔር። ፊትህን አትመልስ።', 'Main subject: Jesus Christ ("ክርስቶስ"×8). Also: Repentance ("መሐረነ"×8); Prayer ("ስማን"×18). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('ebca453d-22da-4651-b371-acbba14506b9'::uuid, array['repentance']::text[], array[]::text[], 'high', 'በደል በዝቶ ለራሴ ሳላውቅ በኃጢአት ሞቼ', 'Theme-centred hymn: Repentance ("ኃጢአት"×2, "በደል"×2, "በደሌ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('ec0fa4e1-100f-48a6-83ef-8181628e8a6c'::uuid, array['repentance']::text[], array[]::text[], 'high', 'የክርስቶስ ድምፁ በግልፅ ይሰማኛል።', 'Main subject: Jesus Christ ("ክርስቶስ"×4, "ጌታዬ"×6, "ኢየሱስ"×1). Also: Repentance ("ማረኝ"×2, "በደሌ"×1, "በደል"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('ecf3d348-0aa6-485a-b1dd-2cd6ba86e2a1'::uuid, array['repentance', 'mercy']::text[], array[]::text[], 'high', 'ቸሩ መድሃኒዓለም እባክህ ማረን /2/ / ተገርፎ ተሰቅሎ ቀራንዮ ዋለ /2/', 'Main subject: Jesus Christ ("ክርስቶስ"×3, "መድኃኒዓለም"×1). Also: Repentance ("ኃጢያት"×2, "በደል"×2, "ይቅርታ"×1); Cross ("መስቀል"×3). Occasion evidence: Siklet ("ቀራንዮ"×3, "የእሾህ አክሊል"×1, "ተሰቅሎ"×1); Communion ("ሥጋ … ደም (Body and Blood)"×1).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('ed7486fa-df58-49f6-b383-132071f92632'::uuid, array['repentance', 'prayer']::text[], array[]::text[], 'high', 'May the rest of my days be spent in repentance', 'Theme-centred hymn: Repentance ("my sins"×2, "Repentance"×1); no single person or saint dominates. Also: Prayer ("Prayer"×1, "help me"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('ef9ed40c-ee25-478a-bfca-8322e69931e3'::uuid, array['repentance']::text[], array[]::text[], 'high', 'የጠፋው ልጅህን በብዙ ታገስከኝ', 'Theme-centred hymn: Repentance ("የጠፋው ልጅ"×1, "ንስሐ"×1); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('f0d1e1dc-69f8-4d9e-969b-1050e188fe75'::uuid, array['repentance']::text[], array[]::text[], 'high', 'ይታያል ኃጢአቴ፣ የበደል እርቃኔ።', 'Theme-centred hymn: Repentance ("በደሌ"×4, "ኃጢአቴ"×3, "ኃጢአት"×2); no single person or saint dominates. No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('f4b31d46-09b7-4598-b5a5-14d3bf59e8ec'::uuid, array['repentance']::text[], array[]::text[], 'high', 'You are my reliance for my life salvation', 'Theme-centred hymn: Salvation ("Salvation"×10); no single person or saint dominates. Also: Repentance ("my sins"×1, "ኃጢአቴ"×1, "በደሌ"×1). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28'),
    ('f656b663-6b3e-4dff-838f-fe4124f853bc'::uuid, array['repentance']::text[], array[]::text[], 'high', 'Christ was imprisoned and then Barabbas was freed /2/ / They placed it on His head the braided crown of thorns /2/', 'Main subject: Jesus Christ ("christ"×2, "jesus"×2). Also: Cross ("the cross"×8, "መስቀል"×2); Repentance ("sinner"×2). Occasion evidence: Siklet ("crown of thorns"×2).', false, 'lyrics-alias-classifier-2026-10-28'),
    ('fdf841bb-83c7-4e08-afdd-7573a32deebb'::uuid, array['repentance']::text[], array[]::text[], 'high', 'መድኃኔዓለም የለም የሚሳነው', 'Main subject: Jesus Christ ("መድኃኔዓለም"×2, "አማኑኤል"×1). Also: Repentance ("እንባዬ"×2). No feast or season is named in the lyrics, so General / Anytime.', false, 'lyrics-alias-classifier-2026-10-28')
on conflict (mezmur_import_id) do update set
  themes = excluded.themes,
  specific_occasion_slugs = excluded.specific_occasion_slugs,
  confidence = excluded.confidence,
  supporting_lyric_excerpt = excluded.supporting_lyric_excerpt,
  classification_explanation = excluded.classification_explanation,
  review_required = excluded.review_required,
  evidence_source = excluded.evidence_source,
  updated_at = now();

create or replace view public.mezmur_fasting_suitability_public
with (security_barrier = true)
as
select
  s.mezmur_import_id,
  m.slug as mezmur_slug,
  m.primary_language,
  s.themes,
  s.specific_occasion_slugs,
  s.confidence
from public.mezmur_fasting_suitability s
join public.mezmur_data_import m on m.import_id = s.mezmur_import_id
where lower(trim(coalesce(m.status, ''))) = 'published'
  and m.deleted_at is null
  and nullif(trim(coalesce(m.slug, '')), '') is not null
  and s.review_required = false
  and s.confidence = 'high';

revoke all on table public.mezmur_fasting_suitability_public from public;
grant select on table public.mezmur_fasting_suitability_public to anon, authenticated, service_role;

